"""Money helpers. All amounts are integer cents."""

import re

_AMOUNT_RE = re.compile(r"^-?\d+(?:\.\d{1,2})?$")


def to_cents(amount: str) -> int:
    if not isinstance(amount, str):
        raise ValueError(f"invalid amount: {amount!r}")
    amount = amount.strip()
    if not _AMOUNT_RE.match(amount):
        raise ValueError(f"invalid amount: {amount!r}")
    negative = amount.startswith("-")
    if negative:
        amount = amount[1:]
    whole, _, fraction = amount.partition(".")
    fraction = (fraction + "00")[:2]
    cents = int(whole) * 100 + int(fraction)
    return -cents if negative else cents


def fmt(cents: int) -> str:
    sign = "-" if cents < 0 else ""
    cents = abs(cents)
    return f"{sign}{cents // 100}.{cents % 100:02d}"


def round_half_up(numerator: int, denominator: int) -> int:
    """Integer division rounded half away from zero."""
    if denominator == 0:
        raise ZeroDivisionError("division by zero")
    negative = (numerator < 0) != (denominator < 0)
    n, d = abs(numerator), abs(denominator)
    quotient, remainder = divmod(n, d)
    if remainder * 2 >= d:
        quotient += 1
    return -quotient if negative else quotient
EOF

cat > shop/discounts.py <<'EOF'
from .money import round_half_up

_PERCENT = {"SAVE10": (10, 0), "SAVE25": (25, 5000)}


def apply_discount(subtotal_cents: int, code) -> int:
    if not code:
        return 0
    if not isinstance(code, str):
        raise KeyError(code)
    code = code.upper()
    if code in _PERCENT:
        pct, minimum = _PERCENT[code]
        if subtotal_cents < minimum:
            return 0
        return max(0, round_half_up(subtotal_cents * pct, 100))
    if code == "FLAT5":
        return max(0, min(500, subtotal_cents))
    raise KeyError(code)
EOF

cat > shop/tax.py <<'EOF'
from .money import round_half_up

# rates in basis points (1/100 of a percent)
RATES_BP = {"UK": 2000, "DE": 1900, "US-CA": 725, "US-OR": 0}


def tax_for(cents: int, region: str) -> int:
    if not isinstance(region, str):
        raise KeyError(region)
    bp = RATES_BP[region.upper()]
    return round_half_up(cents * bp, 10000)
EOF

cat > shop/cart.py <<'EOF'
from .money import to_cents
from .discounts import apply_discount
from .tax import tax_for


class Cart:
    def __init__(self, region: str):
        self.region = region
        self._lines = []  # [sku, qty, unit_cents]

    def add(self, sku: str, qty: int, unit_price: str) -> None:
        if qty < 1:
            raise ValueError("qty must be >= 1")
        price = to_cents(unit_price)
        for line in self._lines:
            if line[0] == sku:
                if line[2] != price:
                    raise ValueError("unit price does not match existing line")
                line[1] += qty
                return
        self._lines.append([sku, qty, price])

    def remove(self, sku: str, qty: int) -> None:
        for index, line in enumerate(self._lines):
            if line[0] == sku:
                if qty > line[1]:
                    raise ValueError("removing more than present")
                line[1] -= qty
                if line[1] == 0:
                    del self._lines[index]
                return
        raise ValueError(f"no such sku {sku}")

    def lines(self):
        return [tuple(l) for l in self._lines]

    def subtotal(self) -> int:
        return sum(q * u for _, q, u in self._lines)

    def totals(self, code=None) -> dict:
        subtotal = self.subtotal()
        discount = apply_discount(subtotal, code)
        taxable = subtotal - discount
        tax = tax_for(taxable, self.region)
        return {"subtotal": subtotal, "discount": discount, "taxable": taxable,
                "tax": tax, "total": taxable + tax}
EOF
